args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birth WHERE {
  VALUES ?film { dbr:The_Korean_Wedding_Chest dbr:True_to_the_Navy }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?director dbp:birthDate ?birthDate2 . }
  OPTIONAL { ?director dbp:birth_date ?birthDate3 . }
  BIND(COALESCE(?birthDate, ?birthDate2, ?birthDate3) AS ?birth)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }
  FILTER(BOUND(?birth))
}
ORDER BY ASC(?birth)
LIMIT 1

